    "keystore_password", "truststore_password"
}

# Keywords that combined with value patterns indicate credentials
credential_context_keywords := {
    "boot_command", "user_data", "init_script", "setup_script", "provisioning_script",
    "bootstrap_user", "setup_account"
}

has_credential_keyword(name) {
    lower_name := lower(name)
    keyword := credential_keywords[_]
    contains(lower_name, keyword)
}

has_strict_credential_keyword(name) {
    lower_name := lower(name)
    keyword := strict_credential_keywords[_]
    contains(lower_name, keyword)
}

looks_like_password(value) {
    count(value) >= 6
    regex.match("[^a-zA-Z0-9]", value)
}

looks_like_env_var_assignment(value) {
    parts := split(value, "=")
    count(parts) == 2
    key_part := parts[0]
    val_part := parts[1]
    lower_key := lower(key_part)
    password_indicator := {_ | _ := strict_credential_keywords[_]; contains(lower_key, _)}[_]
    count(val_part) > 0
}

