}

is_string_literal(x) {
    x.ir_type == "String"
    count(x.value) > 0
}

# Check if string looks like a file path (keystore, truststore, etc.)
is_file_path(value) {
    regex.match("^[.\\./].*$", value)
} else {
    regex.match(".*\\.[a-zA-Z0-9]+$", value)
}

