    attr.ir_type == "Attribute"

    is_string_literal(attr.value)
    has_strict_credential_keyword(attr.name)
    not contains_safe_reference(attr.value)
    not is_file_path(attr.value.value)

    result := {
        "type": "sec_hard_pass",
        "element": attr,
